/* Resource browsing stays on-device. YouTube is contacted only after a viewer
   explicitly loads a player or follows a creator link. */
window.ResourceLibrary = (() => {
  const e = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const ages = [['all','All ages & adults'],['prek','PreK–K'],['lower','Grades 1–3'],['upper','Grades 4–5'],['middle','Grades 6–8'],['high','Grades 9–12'],['adult','Parents & educators']];
  const kinds = [['all','All invitations'],['move','Move & stretch'],['calm','Pause & settle'],['feelings','Explore feelings'],['connect','Friendship & connection'],['adults','For grown-ups']];
  const kitInfo = [
    {id:'puppets', title:'Buddy puppets', file:'buddy-puppets', label:'COLOR · CUT · TELL', grade:'PreK–3 with support', time:'15–25 min', description:'Give a paper buddy a name, a voice, and a story of its own. Choose a bear, bunny, kitten, or fox.', skill:'Coloring, cutting around large shapes, and assembling.', story:'“My buddy needs…” Try a reply, then switch roles.', materials:'Paper, coloring tools, scissors with adult support, tape, and a folded paper handle.', access:'An adult can cut first. Point to a buddy or use the whole sheet as a story board.', lesson:'sensory', lessonName:'Tactile Storytelling', action:'#companion?view=make', actionName:'Make a digital buddy'},
    {id:'scenes', title:'Foldable story scenes', file:'foldable-story-scenes', label:'FOLD · IMAGINE · RETELL', grade:'K–5 with support', time:'20–30 min', description:'Make a little stage for a big idea. Fold a scene, add characters, and tell what happens first, next, and last.', skill:'Folding, placing pieces, and coordinating both hands.', story:'“At first… Then we tried… In the end…” Change the ending together.', materials:'Paper, crayons or pencils, and optional scissors and tape.', access:'Keep the scene flat, ask a partner to fold, or tell the story by pointing, drawing, or using AAC.', lesson:'sensory', lessonName:'Tactile Storytelling', action:'#together?mode=learner&band=younger&cast=buddy', actionName:'Try a story together'},
    {id:'habitats', title:'Habitat cutouts', file:'habitat-cutouts', label:'SORT · COUNT · WONDER', grade:'K–2 with support', time:'20–30 min', description:'Build a pond and woodland scene. Move the animals, explain your choices, and collect a little data.', skill:'Cutting, arranging, marking tallies, and drawing.', story:'“What does this animal need?” A buddy can help make a plan for its home.', materials:'Paper, coloring tools, scissors with adult support, and optional reusable adhesive.', access:'Use adult-cut pieces or point to animal pictures. Count aloud, make marks, or use objects to show each total.', lesson:'habitats', lessonName:'Animal Habitat Sorting', action:'#studio', actionName:'Open Maker Studio'},
  ];
  let root = null, dialog = null, trigger = null;
  const state = { age:'all', kind:'all', length:'all', query:'' };
  const videos = () => window.WatchVideos || [];
  function icon(kind) {
    const paths = { make:'<path d="M10 9h25v31H10zM17 16h11M17 23h11M17 30h7"/><path d="m33 25 10-10 5 5-10 10-7 2z"/>', move:'<circle cx="30" cy="12" r="5"/><path d="m12 24 17-5 18 7M29 19l-2 18-13 12m13-12 14 12"/>', calm:'<path d="M10 26q9-16 20 0t20 0M10 36q9-16 20 0t20 0"/>', feelings:'<path d="M30 47 10 28C-3 9 23 3 30 19 37 3 63 9 50 28Z"/>', connect:'<circle cx="19" cy="19" r="7"/><circle cx="43" cy="19" r="7"/><path d="M6 47V37q13-17 26 0v10M32 37q13-17 24 0v10"/>', adults:'<path d="M7 12q12-5 23 3 12-8 23-3v35q-12-5-23 3-11-8-23-3ZM30 15v35M13 22h10M37 22h10M13 30h10M37 30h10"/>' };
    return `<svg viewBox="0 0 62 60" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[kind] || paths.feelings}</svg>`;
  }
  function homeCards() {
    return `<section class="resource-entry" aria-labelledby="resourceEntryTitle"><div><p class="eyebrow">FOR HOME, CLASSROOM & EVERYWHERE BETWEEN</p><h2 id="resourceEntryTitle">A little inspiration. Something to make.</h2><p>Find a printable project or choose a video to explore together.</p></div><div class="resource-entry-grid"><a href="#printmake" class="resource-entry-card">${icon('make')}<div><h3>Print & Make</h3><p>Buddy puppets, story scenes, and habitat cutouts.</p><span>Explore the printable kits →</span></div></a><a href="#watch" class="resource-entry-card">${icon('move')}<div><h3>Watch & Learn</h3><p>Movement, quiet moments, and ideas for caring.</p><span>Find a video for your moment →</span></div></a></div></section>`;
  }
  function header(type) {
    return `<nav class="resource-switch" aria-label="Resource collections"><a href="#printmake" ${type==='print'?'aria-current="page"':''}>Print & Make</a><a href="#watch" ${type==='watch'?'aria-current="page"':''}>Watch & Learn</a></nav>`;
  }
  function print(target) {
    root = target;
    root.innerHTML = `<div class="resource-page">${header('print')}<section class="resource-hero"><div><p class="eyebrow">PAPER, POSSIBILITY & YOUR OWN IDEAS</p><h1>Print & Make</h1><p class="resource-lead">Little projects. Stories only you can tell.</p><p>Bring your buddy off the screen. Color, fold, arrange, and tell a story in your own way.</p></div><div class="resource-hero-note">${icon('make')}<strong>Made to share</strong><p>Free original kits for home and classroom use. Every kit includes a way to join in without cutting.</p></div></section><div class="resource-guide"><span class="resource-step">01 <b>Choose a kit</b></span><span class="resource-step">02 <b>Print the pages you need</b></span><span class="resource-step">03 <b>Make it your own</b></span></div><section aria-label="Printable project kits" class="print-grid">${kitInfo.map((kit,i)=>`<article class="resource-card print-card" id="kit-${kit.id}"><div class="print-cover"><span class="paper-label">PROJECT 0${i+1}</span><img src="printables/${kit.file}-preview.png" width="510" height="660" alt="Preview of the ${e(kit.title.toLowerCase())} printable template" loading="lazy" /></div><div class="resource-card-body"><p class="eyebrow">${kit.label}</p><h2>${kit.title}</h2><p>${kit.description}</p><div class="resource-tags"><span>${kit.grade}</span><span>${kit.time}</span><span>4 pages · PDF</span></div><p class="resource-skill"><b>Hands-on practice</b><br>${kit.skill}</p><details><summary>Materials & ways to join</summary><p><b>Gather:</b> ${kit.materials}</p><p><b>Another way:</b> ${kit.access}</p><p><b>Try a story:</b> ${kit.story}</p></details><div class="resource-actions"><a class="resource-button primary-link" href="printables/${kit.file}.pdf" download="${kit.file}.pdf">Download PDF <span aria-hidden="true">↓</span></a><a href="printables/${kit.file}.pdf" target="_blank" rel="noopener noreferrer" aria-label="Preview ${kit.title} PDF in a new tab">Preview kit ↗</a></div><div class="resource-meta"><button class="resource-text-button" data-kit-lesson="${kit.lesson}">Lesson: ${kit.lessonName} →</button><a href="${kit.action}">${kit.actionName} →</a></div></div></article>`).join('')}</section><section class="resource-bottom-note"><h2>Follow the maker’s pace.</h2><p>These are invitations to practice using hands and telling stories. Choose larger pieces, ask someone to help, or use the pages without scissors. An adult should supervise cutting and choose suitable tools.</p><p>Print in black and white on US Letter paper. Choose “Fit” for A4; follow the cutting and folding key in each kit.</p><a href="https://ctmuhb.nhs.wales/services/occupational-therapy-for-children/developing-scissor-skills/" target="_blank" rel="noopener noreferrer">For adults: guidance on developing scissor skills ↗</a></section></div>`;
    root.querySelectorAll('[data-kit-lesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.kitLesson));
  }
  function matches(video, filter) {
    const q = (filter.query || '').trim().toLowerCase();
    return (filter.age==='all' || video.ages.includes(filter.age)) && (filter.kind==='all' || video.kinds.includes(filter.kind)) &&
      (filter.length==='all' || (Number.isFinite(video.seconds) && (filter.length==='short' ? video.seconds<=180 : filter.length==='medium' ? video.seconds>180 && video.seconds<=360 : video.seconds>360))) &&
      (!q || [video.title,video.creator,video.description,...video.kinds].join(' ').toLowerCase().includes(q));
  }
  const duration = v => Number.isFinite(v.seconds) ? `${Math.floor(v.seconds/60)}:${String(v.seconds%60).padStart(2,'0')}` : 'Length on creator page';
  const ageText = v => v.audience || v.ages.map(id=>ages.find(a=>a[0]===id)?.[1]).filter(Boolean).join(' · ');
  function watch(target) {
    root = target;
    Object.assign(state,{age:'all',kind:'all',length:'all',query:''});
    const params = new URLSearchParams(location.hash.split('?')[1]||'');
    if(ages.some(a=>a[0]===params.get('age'))) state.age=params.get('age');
    if(kinds.some(a=>a[0]===params.get('kind'))) state.kind=params.get('kind');
    root.innerHTML = `<div class="resource-page">${header('watch')}<section class="resource-hero"><div><p class="eyebrow">A MOMENT TO MOVE, WONDER OR CONNECT</p><h1>Watch & Learn</h1><p class="resource-lead">Find something for this moment.</p><p>Explore creator videos for children, teens, and the grown-ups beside them. Choose an age group and the kind of moment you need.</p></div><div class="resource-hero-note">${icon('calm')}<strong>You choose the pace</strong><p>Nothing plays automatically. Read the notes, preview together, and choose what feels right today.</p></div></section><section class="resource-filters" aria-label="Find a video"><label>Who is watching?<select id="videoAge">${ages.map(([id,label])=>`<option value="${id}" ${state.age===id?'selected':''}>${label}</option>`).join('')}</select></label><label>What would help?<select id="videoKind">${kinds.map(([id,label])=>`<option value="${id}" ${state.kind===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Time available<select id="videoLength"><option value="all">Any length</option><option value="short">Up to 3 minutes</option><option value="medium">3–6 minutes</option><option value="long">Over 6 minutes</option></select></label><label>Find a topic<input id="videoSearch" type="search" placeholder="Sharing, breathing, GoNoodle…" maxlength="120" /></label><button id="videoReset" type="button">Reset filters</button></section><div class="resource-results-header"><p id="videoCount" role="status" aria-live="polite"></p><span>Creator videos · Selected resources</span></div><section id="videoCards" class="video-grid" aria-label="Video recommendations"></section><details class="resource-review-note"><summary>How this collection is selected</summary><p>We select official creator uploads with a clear age or audience fit and an opportunity to practice, reflect, or take a voluntary break. A movement break is labeled separately from SEL instruction. Age suggestions are starting points; preview the language, pace, sound, and movement for your learners.</p><p>Source pages, review notes, and an off-screen invitation accompany each video. This is a resource collection, not a ranking or a claim that each video improves SEL. Captions and availability can change. YouTube may show ads or recommendations.</p><p>Creator information checked October 2026. Videos and their characters belong to the credited creators. Our printable kits are original SNOW DAY Learning Lab resources.</p></details></div>`;
    for(const [id,key] of [['videoAge','age'],['videoKind','kind'],['videoLength','length']]) root.querySelector('#'+id).onchange=event=>{state[key]=event.target.value;drawVideos();};
    root.querySelector('#videoSearch').oninput=event=>{state.query=event.target.value;drawVideos();};
    root.querySelector('#videoReset').onclick=()=>{Object.assign(state,{age:'all',kind:'all',length:'all',query:''});for(const id of ['videoAge','videoKind','videoLength'])root.querySelector('#'+id).value='all';root.querySelector('#videoSearch').value='';drawVideos();root.querySelector('#videoAge').focus();};
    drawVideos();
  }
  function drawVideos() {
    const list=videos().filter(v=>matches(v,state));
    root.querySelector('#videoCount').textContent=`${list.length} ${list.length===1?'video':'videos'} to explore`;
    root.querySelector('#videoCards').innerHTML=list.length?list.map(v=>`<article class="resource-card video-card"><div class="video-cover" data-kind="${e(v.kinds[0])}">${icon(v.kinds[0])}<span class="video-duration">${duration(v)}</span><span class="video-kind">${e(kinds.find(k=>k[0]===v.kinds[0])?.[1]||'Explore together')}</span></div><div class="resource-card-body"><p class="eyebrow">${e(v.creator)}</p><h2>${e(v.title)}</h2><p>${e(v.description)}</p><div class="resource-tags"><span>${e(ageText(v))}</span></div><p class="video-note">${e(v.sensory)}</p><button class="resource-video-open" data-video="${e(v.id)}" aria-label="View ${e(v.title)}">View video <span aria-hidden="true">↗</span></button></div></article>`).join(''):`<div class="resource-empty"><h2>No videos match yet.</h2><p>Try a different age, topic, or length, or reset the filters to see the whole collection.</p></div>`;
    root.querySelectorAll('[data-video]').forEach(b=>b.onclick=()=>showVideo(b.dataset.video,b));
  }
  function showVideo(id, button) {
    const v=videos().find(v=>v.id===id); if(!v) return;
    trigger=button; dialog=document.createElement('dialog'); dialog.className='resource-video-dialog'; dialog.setAttribute('aria-labelledby','videoTitle');
    dialog.innerHTML=`<div class="resource-dialog-header"><span class="eyebrow">${e(v.creator)} · ${duration(v)}</span><button id="closeVideo" aria-label="Close video">✕</button></div><h2 id="videoTitle">${e(v.title)}</h2><p>${e(ageText(v))}</p><div id="videoPlayer" class="video-player"><div class="video-player-placeholder">${icon(v.kinds[0])}<button class="primary" id="loadVideo">Load YouTube player</button><p>The player connects to YouTube. Press play there when you’re ready.</p></div></div><div class="resource-actions"><a href="https://www.youtube.com/watch?v=${e(v.youtubeId)}" target="_blank" rel="noopener noreferrer">Watch on YouTube ↗</a><a href="${e(v.source)}" target="_blank" rel="noopener noreferrer">Creator’s resource page ↗</a></div><p>${e(v.description)}</p><dl class="video-details"><div><dt>Before you watch</dt><dd>${e(v.sensory)}</dd></div><div><dt>Captions & language</dt><dd>${e(v.captions)}</dd></div><div><dt>Selection note</dt><dd>${e(v.review)}</dd></div></dl><section class="resource-followup"><p class="eyebrow">BRING IT OFF THE SCREEN</p><h3>One little invitation</h3><p>${e(v.followup)}</p><a href="${e(v.related || '#printmake')}">Explore a related activity →</a></section>`;
    document.body.append(dialog);
    dialog.querySelector('#closeVideo').onclick=()=>dialog.close();
    dialog.querySelector('#loadVideo').onclick=()=>{
      const frame=document.createElement('iframe'); frame.title=v.title+' — '+v.creator; frame.src=`https://www.youtube-nocookie.com/embed/${v.youtubeId}?playsinline=1&rel=0`;frame.allow='encrypted-media; picture-in-picture; fullscreen';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';
      dialog.querySelector('#videoPlayer').replaceChildren(frame);
    };
    dialog.addEventListener('close',()=>{const node=dialog;dialog=null;node?.remove();document.removeEventListener('visibilitychange',hideVideo);if(trigger?.isConnected)trigger.focus();trigger=null;},{once:true});
    dialog.querySelector('.resource-followup a').onclick=()=>dialog.close();
    dialog.showModal();
    document.addEventListener('visibilitychange',hideVideo);
  }
  function hideVideo(){if(document.hidden) closeVideo();}
  function closeVideo(){dialog?.close();document.removeEventListener('visibilitychange',hideVideo);}
  function stop(){closeVideo();root=null;}
  return {print,watch,stop,closeVideo,homeCards,matches,kits:kitInfo,ages,kinds};
})();
